def capture(slug,num):
    if (slug,num) in by:return by[slug,num]
    item=next(x for x in json.loads((B.parent/'sites/liberer-la-retraite/dist/corpus'/(slug+'.json')).read_text())if x['number']==num)
    key=item['code_id'],item['source_id'];a=dict(c.execute('select * from articles where code_id=? and id=?',key).fetchone());raw=c.execute('select xml from documents where code_id=? and id=? and kind="ARTICLE"',key).fetchone()[0];raw=raw.decode()if isinstance(raw,bytes)else raw
    a['source_id']=a.pop('id');a['source_xml']=a.pop('content_xml');a['source_notes_xml']=source_notes(c,*key);a['source_document_xml']=raw;a['source_document_sha256']=sha(raw);a['source_body_sha256']=sha(a['source_xml']);a['source_notes_sha256']=sha(a['source_notes_xml']);d=c.execute('select * from drafts where code_id=? and source_id=?',key).fetchone();a['previous_draft']=dict(d)if d else None;a['current_beforeimage_sha256']=sha(d['proposed_xml'])if d else None;a['source_url']='https://www.legifrance.gouv.fr/codes/article_lc/'+a['source_id'];a['slug']=slug;a['benefit_check_required']=True;assert sha(raw)==a['source_sha256'];by[slug,num]=a;return a
sources=[];answers=[];audit=[]
def base(s):return (s['previous_draft']or{}).get('proposed_xml')or s['source_xml']
def replace(body,old,new):
    assert body.count(old)==1,(old,body.count(old));return body.replace(old,new,1)
def add(slug,num,body,reason,notes,benefit,removed=None):
    s=capture(slug,num);assert body!=base(s);a={k:s[k]for k in ['code_id','source_id','source_sha256','number']};a.update(proposed_xml=body,reason=reason,review_notes=notes,benefit_review=benefit)
    if removed:a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    body=body.replace('agents non titulaires de droit public mentionnés à la phrase précédente','agents non titulaires de droit public').replace("autre qu'un ancien contrat à durée indéterminée","autre qu'un contrat à durée indéterminée")
    body=re.sub(r'\s(?:align|border)="[^"]*"','',body)
    a['proposed_xml']=body
    sources.append(s);answers.append(a);audit.append({'slug':slug,'number':num,'source_id':s['source_id'],'previous_draft_present':bool(s['previous_draft']),'previous_proposed_sha256':s['current_beforeimage_sha256'],'proposed_sha256':sha(body),'decision':reason,'benefit_review':benefit,'notes':notes})
S='securite-sociale';T='impots';H='construction-habitation'
phase="une affectation temporaire réelle de remplacement, d'accroissement temporaire d'activité, de travail saisonnier ou d'usage par nature temporaire, ou une période limitée d'apprentissage, de professionnalisation, de formation, d'insertion ou de reconversion"
definition="<p>Pour les contrats uniques conclus à compter de l'entrée en vigueur de la réforme du contrat unique, les facultés du deuxième alinéa du présent III s'appliquent également pendant "+phase+". La durée à retenir est celle de l'affectation ou de la période, prévue lors de son commencement, ou sa durée minimale lorsque sa fin dépend d'un événement. Son objet et sa durée peuvent être établis par les documents de travail ou de formation déjà disponibles, sans formalité déclarative nouvelle. Cette durée ne constitue ni un terme du contrat de travail ni une dispense de rémunération entre deux affectations. La durée de couverture s'apprécie sur cette période, sans tenir compte de la portabilité prévue à l'article L. 911-8. À la fin de cette période, le salarié demeurant employé bénéficie de la couverture collective obligatoire, sauf autre cas de dispense applicable à sa situation. Les anciens contrats conservent les facultés de dispense et les droits qui leur sont applicables.</p>"
s=capture(S,'L135-9');b=base(s);b=replace(b,"Il conclut avec eux des contrats à durée déterminée ou indéterminée.","Les agents de droit privé recrutés à compter de l'entrée en vigueur de la réforme du contrat unique sont employés sous contrat unique à durée indéterminée. Les contrats des agents de droit public restent régis par les dispositions qui leur sont propres et peuvent être à durée déterminée ou indéterminée. Les contrats antérieurement conclus, leurs créances et leurs droits acquis sont préservés.")
add(S,'L135-9',b,"Distinguer le recrutement privé futur sous contrat unique des contrats publics du fonds.","Le droit public n'est pas soumis au préavis ni au barème du régime privé par le présent article ; les deux phrases de l'avant-image sont conservées sauf coordination du recrutement.","La faculté de recrutement du fonds et la prise en charge de ses frais restent entières. Les agents publics gardent leurs modes de recrutement et les agents déjà engagés leurs contrats, ancienneté et créances.")
s=capture(S,'L767-1');b=base(s);b=replace(b,"Ce centre peut également recruter des agents de droit privé régis par les conventions collectives applicables au personnel des organismes de sécurité sociale.","Ce centre peut également recruter des agents de droit privé régis par les conventions collectives applicables au personnel des organismes de sécurité sociale. Les recrutements de droit privé effectués à compter de l'entrée en vigueur de la réforme du contrat unique prennent la forme du contrat unique à durée indéterminée ; les contrats déjà conclus et leurs droits acquis sont préservés. Les contrats à durée déterminée ou indéterminée des agents non titulaires de droit public mentionnés à la phrase précédente restent soumis à leur régime propre.")
add(S,'L767-1',b,"Appliquer le contrat unique aux seuls recrutements privés du CLEISS.","Lecture entière : établissement administratif, missions, réserve L221-1 10°, contributions des régimes et titularisation des lois1984/2001 intacts. Aucun alignement silencieux des agents publics sur le régime privé.","Les droits à titularisation, les conventions collectives, les contrats antérieurs et le financement de l'établissement demeurent. Le nouveau CDI ne supprime ni un droit de l'agent public ni une faculté de recrutement public.")
s=capture(S,'L911-7');b=base(s);needle="<p>Un décret fixe, en outre, les catégories de salariés";assert needle in b;b=b.replace(needle,definition+'\n'+needle,1)
add(S,'L911-7',b,"Maintenir la dispense choisie de couverture courte pour les futures affectations temporaires du contrat unique.","Couverture minimale I/II, financement employeur au moins moitié III, contrat responsable, preuve d'autre couverture et adaptation Alsace-Moselle IV conservés intégralement. Seuil réglementaire D911-6 de trois mois inchangé ; définition de période sans terme d'emploi ajoutée avant le décret des autres dispenses.","La dispense demeure à l'initiative du salarié, avec autre couverture responsable et même seuil de trois mois. Elle reste ouverte aux futurs remplacements/saisons/missions/formations équivalents, sans priver le salarié maintenu en emploi de sa couverture après cette phase.")
s=capture(S,'L911-7-1');b=base(s);b=replace(b,"des salariés en contrat à durée déterminée, en contrat de mission ou à temps partiel mentionnés au présent article","des salariés en contrat à durée déterminée, en contrat de mission, sous contrat unique pendant les affectations ou périodes temporaires définies au III de l'article L. 911-7, ou à temps partiel mentionnés au présent article")
b=replace(b,"de la durée du contrat et de la durée de travail prévue par celui-ci.","de la durée du contrat ou, pour le contrat unique, de l'affectation ou de la période temporaire définie au III de l'article L. 911-7, et de la durée de travail prévue pendant la période concernée.")
b=replace(b,"dont la durée du contrat ou la durée du travail prévue par celui-ci est inférieure à des seuils","dont la durée du contrat, de l'affectation ou de la période temporaire définie au III de l'article L. 911-7, ou la durée du travail prévue pendant la période concernée, est inférieure à des seuils")
b+='\n<p>La fin d\'une affectation ou d\'une période temporaire sous contrat unique ne rompt pas l\'emploi. Lorsque le salarié demeure employé, le versement ne se substitue à la couverture collective que tant que les conditions du présent article restent remplies. Les droits aux versements afférents aux anciens contrats sont conservés.</p>\n'
add(S,'L911-7-1',b,"Conserver le versement santé employeur et ses modalités pour les périodes temporaires des nouveaux CDI.","I àIV entiers ; assurance responsable, non-cumuls, accords de branche/entreprise, décision unilatérale et exclusion des salariés déjà couverts conservés. La référence à l'avant-dernier alinéa III est conservée : aucun alinéa n'est ajouté dans ce III.","La somme représentative du financement, la dispense IV et l'accès à temps partiel subsistent. La durée limitée de la phase remplace le support CDD sans remplacer la durée de l'emploi, et sans exclusion des futurs bénéficiaires.")
s=capture(S,'R242-1-6');b=base(s)
b=replace(b,"a) Des salariés et apprentis bénéficiaires d'un contrat à durée déterminée ou d'un contrat de mission d'une durée au moins égale à douze mois","a) Des salariés et apprentis bénéficiaires d'un contrat à durée déterminée ou d'un contrat de mission d'une durée au moins égale à douze mois, ou d'un contrat unique comportant une affectation ou une période temporaire définie au III de l'article L. 911-7 d'une durée au moins égale à douze mois")
b=replace(b,"b) Des salariés et apprentis bénéficiaires d'un contrat à durée déterminée ou d'un contrat de mission d'une durée inférieure à douze mois,","b) Des salariés et apprentis bénéficiaires d'un contrat à durée déterminée ou d'un contrat de mission d'une durée inférieure à douze mois, ou d'un contrat unique comportant une affectation ou une période temporaire définie au III de l'article L. 911-7 d'une durée inférieure à douze mois,")
b+='\n<p>Pour les contrats uniques, les dispenses prévues aux a et b du 2° ne s\'appliquent que pendant l\'affectation ou la période temporaire concernée ; la durée à retenir et le maintien de l\'emploi sont appréciés dans les conditions du III de l\'article L. 911-7. Les anciens contrats et les demandes de dispense régulièrement formées conservent leurs droits.</p>\n'
add(S,'R242-1-6',b,"Maintenir les dispenses collectives aux futurs salariés et apprentis en phase temporaire.","Les cas1°/2°c àf, seuil10% du brut, demande informée et protection article11 loi1989 restent entiers. Le seuil douze mois et la distinction avec/sans autre couverture sont strictement conservés.","Toutes les dispenses existantes sont maintenues : couverture individuelle, temps partiel/apprentis10%, couverture solidaire ou collective et salariés présents lors de la décision unilatérale. Les casCDD/missions restent ouverts dans leurs mêmes durées matérielles sous CDI.")
s=capture(S,'D911-5');b='<p>Les demandes de dispense mentionnées au III de l\'article L. 911-7 sont formulées au moment de l\'embauche ou, si elles sont postérieures, à la date de mise en place des garanties ou à celle de prise d\'effet des couvertures mentionnées aux 1° et 3° de l\'article D. 911-2.</p><p>Pour les contrats uniques, elles peuvent également être formulées au commencement d\'une affectation ou d\'une période temporaire définie au III de l\'article L. 911-7 lorsque les conditions de la dispense sont alors réunies. Les demandes déjà régulièrement formées et les droits attachés aux anciens contrats sont conservés.</p>'
add(S,'D911-5',b,"Permettre le choix de dispense au début d'une phase temporaire située après l'embauche en CDI.","Les trois dates de demande antérieures sont maintenues ; pas de délai nouveau ni de déclaration administrative. Coordination nécessaire pour ne pas fermer le droit lorsque la phase commence en cours de contrat.","Les salariés gardent la possibilité de demande à l'embauche, lors de création des garanties ou d'autre couverture ; les futurs salariés en phase temporaire disposent aussi de la demande au commencement de cette phase.")
s=capture(S,'D911-7');b='<p>Les salariés mentionnés au III de l\'article L. 911-7-1 sont ceux dont la durée du contrat de travail ou du contrat de mission, ou celle de l\'affectation ou de la période temporaire définie au III de l\'article L. 911-7 dans un contrat unique, est inférieure ou égale à trois mois, ou ceux dont la durée effective du travail prévue pendant la période concernée est inférieure ou égale à 15 heures par semaine.</p><p>Pour le contrat unique, cette durée n\'est pas un terme de l\'emploi. Les anciens contrats et les droits aux versements déjà constitués sont préservés.</p>'
add(S,'D911-7',b,"Conserver les seuils trois mois et quinze heures du versement santé sous contrat unique.","Seuils inchangés ; alternative temps partiel conservée, aucun élargissement aux CDI permanents à temps plein. La définition législative de la période évite une fin d'emploi implicite.","Le versement santé reste ouvert aux emplois courts de même objet et aux salariés à quinze heures ou moins. L'accès favorable ne disparaît pas du fait que le nouveau support juridique de l'emploi est indéterminé.")
s=capture(S,'D911-8');b=base(s);b=replace(b,"III.-Le coefficient mentionné au I du présent article est égal à 105 % pour les salariés bénéficiant d'un contrat à durée indéterminée et à 125 % pour les salariés bénéficiant d'un contrat à durée déterminée ou d'un contrat de mission.","III.-Le coefficient mentionné au I du présent article est égal à 125 % pour les salariés bénéficiant d'un ancien contrat à durée déterminée ou d'un ancien contrat de mission, ainsi que, pendant la période concernée, pour les salariés sous contrat unique accomplissant une affectation ou une période temporaire définie au III de l'article L. 911-7. Il est égal à 105 % pour les autres salariés bénéficiant d'un contrat à durée indéterminée. La fin de cette affectation ou période ne constitue pas un terme de l'emploi. Les droits aux versements afférents aux périodes antérieures sont conservés.")
add(S,'D911-8',b,"Préserver le coefficient favorable125% du versement santé pour les futurs cas temporaires équivalents.","I/II entièrement conservés : référence employeur, proratas plafonnés1, mise à dispositionL5132-9, plancher15€/5€ et revalorisation annuelle ONDAM ; seulIII change. Arrêtés de revalorisation externes non prétendus réécrits.","Le125% n'est pas réduit automatiquement à105% parce que le contrat devient unique. Le montant de référence, ses minima, la revalorisation et tous proratas antérieurs sont conservés pour les bénéficiaires futurs comme anciens.")
s=capture(S,'R130-1');b=base(s);b=replace(b,"Toutefois, les salariés mentionnés à la deuxième phrase du 2° de l'article L. 1111-2 du code du travail sont exclus du décompte des effectifs.","Toutefois, les salariés recrutés pour remplacer un salarié absent ou dont le contrat est suspendu et les salariés mis à disposition pour ce remplacement, mentionnés au 2° de l'article L. 1111-2 du code du travail, sont exclus du décompte pendant le remplacement, y compris sous contrat unique. Leur maintien en emploi au-delà de ce remplacement relève ensuite des règles ordinaires de décompte.")
b=replace(b,"il est tenu compte des salariés permanents et des salariés qui, au cours de la période, ont été liés à cette entreprise par des contrats de mission.","il est tenu compte des salariés permanents et des salariés qui, au cours de la période, ont été liés à cette entreprise par des anciens contrats de mission ou par des contrats uniques de travail temporaire. Un même salarié n'est compté qu'une fois pour une même période ; la fin d'une mission n'est pas une fin de contrat unique et les périodes d'emploi entre missions restent comprises dans le décompte.")
add(S,'R130-1',b,"Sécuriser l'exclusion favorable des remplaçants et le décompte de l'intérim sous CDI sans double compte.","Le renvoi ordinal ancien devenait fragile après coordination deL1111-2 : désignation matérielle des remplaçants. Moyenne sociale mensuelle, prorata jours/temps partiel, exclusionsIII, transfertV etATMPVI intacts ; aucune transposition du prorata12mois du Travail à la moyenne sociale.","Les remplaçants sous contrat unique restent exclus pendant le remplacement. Les exclusions apprentissage/aides deL1111-3 et les règles de temps partiel sont conservées ; aucun double décompte de l'intérimaire sous CDI n'est créé.")
s=capture(S,'L241-13');b=base(s);needle='<p>III bis.';new='<p>Pour les contrats uniques conclus à compter de l\'entrée en vigueur de la réforme du contrat unique, les modalités de calcul distinct par contrat anciennement applicables aux CDD ou aux contrats de mission restent accessibles, sans rupture d\'emploi, pour chaque affectation temporaire réelle de remplacement, d\'accroissement temporaire d\'activité, de travail saisonnier ou d\'usage par nature temporaire, ou période limitée de formation, d\'insertion ou de reconversion de même objet. L\'employeur peut retenir ce calcul distinct lorsqu\'il procure une réduction supérieure au calcul annuel ordinaire. La rémunération et le salaire minimum de croissance sont alors affectés à la même période, à proportion de sa durée effective ; aucune rémunération ni durée n\'est comptée deux fois. Les autres périodes d\'emploi, y compris entre missions, demeurent prises en compte. L\'affectation ne limite pas la durée du contrat. Les réductions et créances afférentes aux périodes antérieures sont conservées.</p>\n';assert needle in b;b=b.replace(needle,new+needle,1)
add(S,'L241-13',b,"Préserver par la loi le calcul favorable par période temporaire sans contraindre à un nouveauCDD.","Lecture entière du régime2026 : périmètre, plafond3SMIC, formule déléguée,IIIbis favorable, congés/heures équivalentes, non-cumul, imputations et calendrierMayotte conservés. La dérogation au calcul annuelIII est placée avantIIIbis sans modifier les alinéas ciblés à l'intérieur deIII.","Le calcul auparavant distinct parCDD/mission reste proposé si plus favorable, sans double compte. Tous autres allègements, correction congés, cumul heures supplémentaires, taux et seuilsMayotte et dérogationIIIbis demeurent ; aucune cotisation nouvelle ni baisse d'exonération.")
s=capture(S,'D241-7');b=base(s);b=replace(b,"Pour les salariés en contrat à durée déterminée auprès d'un même employeur, le coefficient mentionné au II est déterminé pour chaque contrat.","Pour les salariés en ancien contrat à durée déterminée auprès d'un même employeur, le coefficient mentionné au II est déterminé pour chaque contrat. Pour les contrats uniques, le calcul distinct par affectation ou période temporaire, y compris par mission, prévu au III de l'article L. 241-13 peut être retenu lorsqu'il est plus favorable que le calcul annuel ordinaire, même si le contrat garantit une rémunération minimale entre missions. Les règles du IV de l'article présent sont appliquées à la durée et à la rémunération de chaque période concernée, sans double compte ; la rémunération et la durée des autres périodes, notamment entre missions, restent prises en compte selon les mêmes règles. Les anciens contrats conservent leur régime et leurs créances.")
b=b.replace("du IV de l'article présent","du IV du présent article")
add(S,'D241-7',b,"Conserver le calcul séparé favorable des allègements malgré l'emploi indéterminé et ses intermissions.","Toutes les valeurs2026 et la formule source sont conservées ; le graphisme de puissanceP est textuellement reproduit comme dans le XML canonique et n'est pas reconstruit. L'exception des anciensCDI intérimaires auV demeure ; le nouveau choix plus favorable est expressément fondé surL241-13 proposé. Erreurs préexistantes de renvoisI/II et nombre d'alinéasIV ne sont pas présentées comme résolues par cette seule coordination.","Tmin0,0200, Tdelta0,3781/0,3821, puissance1,75, heures supplémentaires,218jours, proratas d'absence et modalités d'imputation sont intégralement conservés. Le calcul par période ne s'impose jamais s'il réduit l'allègement annuel.")
s=capture(S,'D241-5-2');b=base(s);b=replace(b,"III.-Pour les salariés en contrat à durée déterminée auprès d'un même employeur, le coefficient mentionné au II est déterminé pour chaque contrat.","III.-Pour les salariés en ancien contrat à durée déterminée auprès d'un même employeur, le coefficient mentionné au II est déterminé pour chaque contrat. Pour les contrats uniques, l'employeur peut retenir un calcul distinct pour chaque affectation temporaire réelle de remplacement, d'accroissement temporaire d'activité, de travail saisonnier ou d'usage par nature temporaire, ou période limitée de formation, d'insertion ou de reconversion de même objet, lorsque ce calcul est plus favorable que le calcul annuel ordinaire. Les rémunérations, heures et salaire minimum sont affectés à la même période, selon les I et II et l'article D. 241-7, sans double compte. Les autres périodes d'emploi restent prises en compte ; la fin de l'affectation ne rompt pas le contrat. Les exonérations et créances afférentes aux périodes antérieures sont conservées.")
add(S,'D241-5-2',b,"Maintenir le calcul par période favorable de l'exonération aide à domicile sous contrat unique.","I/II/IV, formule1,2×T/0,4×(1,6×SMIC/rémunération−1), seuilSMIC+20%, plafond et régularisations entièrement conservés. Pas d'affectation fictive fractionnant une période permanente ; aucun cumul deux fois sur les mêmes salaires/heures.","L'exonération aide à domicile conserve son assiette et ses proratas ; l'employeur peut encore obtenir le calcul favorable auparavant lié auCDD sans limiter l'emploi. Le calcul annuel reste possible lorsqu'il procure davantage d'exonération.")
s=capture(H,'L822-7');b='<p>La prise en compte des ressources peut relever de dispositions spécifiques lorsque le demandeur est âgé de moins de vingt-cinq ans et dispose d\'un contrat de travail autre qu\'un ancien contrat à durée indéterminée, ou accomplit, sous contrat unique, '+phase+'.</p><p>Pour le contrat unique, l\'accès à ces dispositions spécifiques s\'apprécie pendant l\'affectation ou la période de même objet ; sa durée ne constitue pas un terme de l\'emploi. Le bénéfice ne peut être refusé au seul motif que le contrat est à durée indéterminée. Les droits afférents aux anciens contrats et aux périodes antérieures sont conservés. Le présent article ne modifie pas les régimes propres aux agents publics.</p>'
add(H,'L822-7',b,"Maintenir l'accès aux règles favorables de ressources logement des moins de25ans après disparition duCDD.","L'âge de25ans et la faculté réglementaire de ressources spécifiques sont conservés ; les situations temporaire/formation de même objet sont énumérées sans faire du CDI un contrat à terme. R822-18 etD822-0-2 seront audités comme dépendances, sans présumer leur réécriture.","Le demandeur de moins de25ans ne perd pas le traitement de ressources lié à la situation temporaire ou de formation parce que son contrat devient unique. Les bénéficiaires antérieurs et les catégories publiques distinctes conservent leurs régimes.")
s=capture(T,'204 H');b=base(s);old="Pour les salaires versés au titre d'un contrat à durée déterminée ou d'un contrat de mission dont le terme initial n'excède pas deux mois ou, s'il s'agit d'un contrat à terme imprécis, dont la durée minimale n'excède pas deux mois, les grilles prévues aux a à c s'appliquent, dans la limite des deux premiers mois d'embauche, aux versements effectués au titre ou au cours d'un mois après un abattement égal à la moitié du montant mensuel du salaire minimum de croissance et sans procéder aux ajustements prévus au premier alinéa du présent d."
new=old+" Pour les contrats uniques conclus à compter de l'entrée en vigueur de la réforme du contrat unique, cet abattement et l'absence d'ajustement sont également applicables, dans la limite des deux premiers mois d'embauche, lorsque le salarié est recruté pour une affectation temporaire réelle de remplacement, d'accroissement temporaire d'activité, de travail saisonnier ou d'usage par nature temporaire, ou une période limitée de formation, d'insertion ou de reconversion de même objet, dont la durée initialement prévue n'excède pas deux mois ou, si sa fin dépend d'un événement, dont la durée minimale n'excède pas deux mois. Cette durée ne constitue pas un terme de l'emploi. La succession d'affectations au sein du même contrat ne fait pas recommencer les deux premiers mois d'embauche. Les droits afférents aux anciens contrats et retenues restent préservés."
b=replace(b,old,new)
add(T,'204 H',b,"Conserver l'abattement de prélèvement à la source des embauches de courte affectation sous CDI.","Lecture intégrale14490caractères source et trois tableaux complets : aucun seuil/taux/ligne modifié. Abattement½SMIC, deux premiers mois, taux nulII29310€, outre-mer et optionIV conservés. AucunIS annuel, succession ouCVAE introduit.","L'abattement½SMIC des courtes embauches reste accessible aux nouveaux contrats uniques de même objet et durée, sans remise à zéro à chaque mission. Les trois grilles, seuils outre-mer et facultés de taux nul ou optionnel demeurent intégralement.")
s=capture(T,'81 bis');b=base(s);b+='\n<p>Pour les contrats uniques conclus à compter de l\'entrée en vigueur de la réforme du contrat unique, les salaires versés pendant la période d\'apprentissage régie par le code du travail bénéficient de cette exonération dans les mêmes conditions et la même limite annuelle, sans que la durée indéterminée de l\'emploi y fasse obstacle. La fin de cette période ne met pas fin au contrat. Les salaires afférents aux anciens contrats et les droits antérieurement constitués sont préservés.</p>\n'
add(T,'81 bis',b,"Rendre expressément applicable l'exonération annuelle aux périodes d'apprentissage du contrat unique.","Avant-image entière conservée : salaires apprentis, gratification stagesL124-6 éducation, plafondSMICannuel, rattachement au foyer. Aucun changement de l'imposition de la rémunération ordinaire hors phase.","L'apprenti futur garde l'exonération dans la limite duSMICannuel et son rattachement fiscal ; le stagiaire conserve sa propre exonération. La durée illimitée de l'emploi ne ferme pas l'avantage pendant la formation ni ne le prolonge artificiellement après elle.")
for num,clause in [('732 ter',"<p>Pour l'application du a du 2° du I, le contrat unique à durée indéterminée ouvre droit au même abattement lorsque la condition de deux ans et de temps plein est remplie. Est également admis, sans cette condition de deux ans, le salarié accomplissant, à la date de la cession, une période d'apprentissage régie par le code du travail au sein de ce contrat unique. Les périodes de travail antérieures conservées dans l'ancienneté sont prises en compte sans remise à zéro. La fin de l'apprentissage n'est pas un terme de l'emploi. Les autres conditions et les droits afférents aux cessions antérieures restent inchangés.</p>"),('790 A',"<p>Pour l'application du b du I, le contrat unique à durée indéterminée ouvre droit au même abattement lorsque la condition de deux ans et de temps plein est remplie. Est également admis, sans cette condition de deux ans, le salarié accomplissant, au jour de la donation, une période d'apprentissage régie par le code du travail au sein de ce contrat unique. Les périodes de travail antérieures conservées dans l'ancienneté sont prises en compte sans remise à zéro. La fin de l'apprentissage n'est pas un terme de l'emploi. Les autres conditions et les droits afférents aux donations antérieures restent inchangés.</p>")]:
    s=capture(T,num);b=base(s)+'\n'+clause+'\n'
    add(T,num,b,"Conserver l'abattement500000€ de transmission au salarié/apprenti sous contrat unique.","Source et éventuelle avant-image entières conservées ; ajout autonome après les subdivisions afin de préserver les renvoisI/II/III. L'apprentissage futur reste une période du CDI et ne devient pas soumis par erreur à deux ans de CDI. Article790A porte seulement sur les donations entre vifs, distinctes des successions supprimées.","L'abattement500000€, l'accès de l'apprenti dès la transmission, l'anciennetéCDI2ans, la poursuite5ans, la non-déchéance en liquidation et la limitation à une opération restent entiers. Aucun rétablissement de droits successoraux ni fermeture aux futurs apprentis.")
s=capture(T,'1452');b=base(s);b+='\n<p>Pour les contrats uniques conclus à compter de l\'entrée en vigueur de la réforme du contrat unique, est assimilé au concours d\'un apprenti mentionné aux 1° et 2° le concours du salarié pendant sa période d\'apprentissage régie par les articles L. 6221-1 à L. 6225-8 du code du travail, sous la même condition d\'âge au début de cette période. La durée indéterminée de l\'emploi ne fait pas perdre l\'exonération pendant l\'apprentissage. La fin de cette période ne met pas fin à l\'emploi et les autres conditions de l\'exonération restent applicables. Les droits afférents aux périodes antérieures sont conservés.</p>\n'
add(T,'1452',b,"Préserver l'exonérationCFE des artisans recourant aux futurs apprentis sous contrat unique.","Source entière : ouvriers1°, veuve2°, aides familiales, sociétésarticle8 et période1467A conservés. AucuneCVAE recréée ; l'assimilation porte sur la période d'apprentissage avec condition d'âge20ans au plus inchangée.","L'exonérationCFE reste ouverte à l'artisan, à la veuve et aux sociétés éligibles avec apprentis20ansauplus, conjoint/PACS/enfants. Le CDI support de la formation ne ferme pas l'avantage ; aucune condition nouvelle ni rétrécissement de l'aide familiale.")
s=capture(T,'231 bis I');b='<p>1. Les rémunérations versées aux apprentis par les entreprises qui emploient au plus dix salariés sont exonérées de la taxe sur les salaires.</p><p>2. (Abrogé pour les salaires versés à compter du 1er janvier 1996).</p><p>3. Pour les entreprises autres que celles mentionnées au1, la partie du salaire versé aux apprentis égale à11% du salaire minimum de croissance n\'est pas soumise à la taxe sur les salaires.</p><p>Les1 et3 s\'appliquent dans les mêmes conditions aux salaires versés pendant la période d\'apprentissage régie par le code du travail au sein d\'un contrat unique, sans que sa durée indéterminée fasse obstacle à l\'exonération. La fin de cette période ne rompt pas l\'emploi. Les droits afférents aux anciens contrats et aux périodes antérieures sont conservés.</p>'
